function hasDuplicate(ids) {
  const seen = new Set();
  for (const id of ids) {
    if (seen.has(id)) return true;
    seen.add(id);
  }
  return false;
}

console.log(hasDuplicate(["ORD-1", "ORD-2", "ORD-3"]));
console.log(hasDuplicate(["ORD-1", "ORD-2", "ORD-1"]));
