class GrowableList {
  constructor() {
    this.capacity = 1;
    this.length = 0;
    this.slots = new Array(1);
    this.copies = 0;
  }

  push(value) {
    if (this.length === this.capacity) {
      const bigger = new Array(this.capacity * 2);
      for (let i = 0; i < this.length; i++) {
        bigger[i] = this.slots[i];
        this.copies++;
      }
      this.slots = bigger;
      this.capacity = bigger.length;
    }
    this.slots[this.length++] = value;
  }
}

const list = new GrowableList();
for (let i = 0; i < 100; i++) list.push(i);
console.log(list.copies, list.capacity);

