function reverseInPlace(items) {
  let left = 0;
  let right = items.length - 1;
  while (left < right) {
    [items[left], items[right]] = [items[right], items[left]];
    left++;
    right--;
  }
  return items;
}

const history = ["ORD-1", "ORD-2", "ORD-3", "ORD-4", "ORD-5"];
reverseInPlace(history);
console.log(history.join(" "));

